          createdById: null,
        },
        {
          id: "person-2",
          firstName: "Jane",
          lastName: "Smith",
          email: null,
          maidenName: null,
          dateOfBirth: null,
          dateOfPassing: null,
          birthPlace: null,
          bio: null,
          photo: null,
          photoUrl: null,
          isDeceased: false,
          privacyLevel: "PRIVATE",
          createdAt: "2024-01-02T12:00:00.000Z",
          updatedAt: "2024-01-02T12:00:00.000Z",
          createdById: null,
        },
      ],
    ],
    [
      "data/users.json",
      [
        {
          id: "user-1",
          email: "admin@example.com",
          name: "Admin User",
          personId: "person-1",
          role: "ADMIN",
          isActive: true,
          mustChangePassword: false,
          invitedById: null,
          createdAt: "2024-01-01T12:00:00.000Z",
          updatedAt: "2024-01-01T12:00:00.000Z",
          lastLoginAt: "2024-01-01T12:00:00.000Z",
        },
      ],
    ],
    [
      "data/relationships.json",
      [
        {
          id: "rel-1",
          personId: "person-1",
