        },
      ],
    ],
    [
      "data/suggestions.json",
      [
        {
          id: "suggestion-1",
          type: "PERSON_UPDATE",
          targetPersonId: "person-1",
          suggestedData: { bio: "Updated bio" },
          reason: "Missing information",
          status: "PENDING",
          submittedById: "user-1",
          reviewedById: null,
          reviewNote: null,
          submittedAt: "2024-01-01T12:00:00.000Z",
          reviewedAt: null,
        },
      ],
    ],
    [
      "data/audit-logs.json",
      [
        {
          id: "audit-1",
          userId: "user-1",
